ga6k(){return"Light"},
ga6j(){return"Dark"},
gaun(){return"App preferences"},
gat0(){return"How do I change the app appearance or follow the system theme?"},
gaqI(){return"Open Settings from the calendar menu and choose Appearance under Preferences. Select System to automatically follow your device theme, or Light or Dark to always use that theme. Your choice is saved for your account on this device or browser."},
gSq(){return"Notifications"},
gSp(){return"Language"},
